strip.begin();
strip.show();
Initializes the NeoPixel LED strip and clears all LEDs.

examples:
#include <Adafruit_NeoPixel.h>

#define LED_PIN 36
#define NUM_LEDS 12

Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.show();
}

void loop() {
  for (int i = 0; i < NUM_LEDS; i++) {
    strip.clear();
    strip.setPixelColor(i, strip.Color(255, 0, 0));
    strip.show();
    delay(200);
  }
}

void setup(){
    pinMode(37, OUTPUT);
}

void loop() {
  digitalWrite(37, HIGH);
   delay(1000);
  digitalWrite(37, LOW);
    delay(1000);
}

sections.description:
In the setup() function configure the buzzer pin as an output:

pinMode(BUZZER_PIN, OUTPUT);

In the loop() function generate a square wave signal by toggling the pin HIGH and LOW to produce the buzzer tone.

examples:
#define BUZZER_PIN 45
#define BEEP_FREQUENCY 2000
#define BEEP_DURATION 200
#define INTERVAL 2000

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  int period = 1000000 / BEEP_FREQUENCY;
  int pulse = period / 2;

  unsigned long startTime = millis();

  while (millis() - startTime < BEEP_DURATION) {
    digitalWrite(BUZZER_PIN, HIGH);
    delayMicroseconds(pulse);
    digitalWrite(BUZZER_PIN, LOW);
    delayMicroseconds(pulse);
  }

  delay(INTERVAL);
}

sections.description:
Initialize the NeoPixel strip in the setup() function:
strip.begin();
strip.show();

Set the color of a specific LED in the loop() function:
strip.setPixelColor(index, strip.Color(R, G, B));
strip.show();

examples:
#include <Adafruit_NeoPixel.h>

#define LED_PIN 1
#define NUM_LEDS 1

Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.show();
}

void loop() {
  strip.setPixelColor(0, strip.Color(255, 0, 0)); // Red
  strip.show();
  delay(1000);

  strip.setPixelColor(0, strip.Color(0, 0, 255)); // Blue
  strip.show();
  delay(1000);
}

sections.description:
Initialize the I2C communication and OLED display inside setup():

Wire.begin(SDA_PIN, SCL_PIN);
display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS);

display.clearDisplay();
display.setTextSize(size);
display.setTextColor(SSD1306_WHITE);
display.setCursor(x, y);
display.println("text");
display.display();

examples:
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C

#define SDA_PIN 9
#define SCL_PIN 8

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void setup() {
  Wire.begin(SDA_PIN, SCL_PIN);

  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println("SSD1306 allocation failed");
    while (1);
  }

  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Hi World!");
  display.display();
}

void loop() {
}

sections.description:
Create a servo object and attach it to a pin in the setup() function:

Servo myServo;
myServo.attach(SERVO_PIN, 500, 2400);

Control the servo angle inside the loop() function using:

myServo.write(angle);

examples:
#include <ESP32Servo.h>

Servo myServo;

#define SERVO_PIN 1

void setup() {
  myServo.attach(SERVO_PIN, 500, 2400);
}

void loop() {
  myServo.write(90);  // Rotate to 90 degrees
  delay(1000);

  myServo.write(0);   // Rotate back to 0 degrees
  delay(1000);
}
